import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    adj = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        m = int(next(it))
        for _ in range(m):
            x = int(next(it))
            if x != i:
                adj[i].append(x)

    color = [-1] * (n + 1)
    color[1] = 0
    q = deque([1])

    while q:
        v = q.popleft()
        for u in adj[v]:
            if color[u] == -1:
                color[u] = color[v] ^ 1
                q.append(u)

    team1 = []
    team2 = []

    for i in range(1, n + 1):
        if color[i] == 0:
            team1.append(i)
        else:
            team2.append(i)

    sys.stdout.write(" ".join(map(str, team1)) + "\n")
    sys.stdout.write(" ".join(map(str, team2)) + "\n")

if __name__ == "__main__":
